import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"The Pulse of Motion: Measuring Physical Frame Rate from Visual Dynamics","description":"","frontmatter":{"title":"The Pulse of Motion: Measuring Physical Frame Rate from Visual Dynamics","arxiv":"2603.14375","date":"2026-03-15","authors":"Xiangbo Gao, Mingyang Wu, Siyuan Yang, Jiongze Yu, Pardis Taghavi, Fangzhou Lin, Zhengzhong Tu","categories":"cs.CV, cs.AI","topics":"物理感知视频生成, 时间尺度评测, 视频质量度量","outline":[2,2]},"headers":[],"relativePath":"papers/2603.14375.md","filePath":"papers/2603.14375.md","lastUpdated":null}'),l={name:"papers/2603.14375.md"};function e(m,s,i,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="the-pulse-of-motion-measuring-physical-frame-rate-from-visual-dynamics" tabindex="-1">The Pulse of Motion: Measuring Physical Frame Rate from Visual Dynamics <a class="header-anchor" href="#the-pulse-of-motion-measuring-physical-frame-rate-from-visual-dynamics" aria-label="Permalink to &quot;The Pulse of Motion: Measuring Physical Frame Rate from Visual Dynamics&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2603.14375" target="_blank" rel="noreferrer">2603.14375</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-03-15（v2 修订于 2026-03-27）</td></tr><tr><td><strong>作者</strong></td><td>Xiangbo Gao, Mingyang Wu, Siyuan Yang, Jiongze Yu, Pardis Taghavi, Fangzhou Lin, Zhengzhong Tu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>直接从画面运动回归视频的「物理帧率」PhyFPS，用它审计出所有主流视频生成器都存在时间尺度漂移，并用重定时把漂移改回来。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v2</strong>（2026-03-27）全文撰写，模型名 Visual Chronometer、benchmark 名 PhyFPS-Bench 与批次记录一致。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型现在能画出锐利的纹理和连贯的镜头运动，但它们不知道自己画的一秒有多长。作者把这个失败模式命名为 <strong>chronometric hallucination</strong>（计时幻觉）：在提示词里没有出现 slow motion、time-lapse 之类速度关键词的前提下，模型仍会把蜂鸟鹰蛾的振翅渲染成极端慢镜头，把人摔到床上的过程渲染得比重力加速度慢得多。视频存成 24 FPS 的容器，但画面里隐含的真实速度可能是 46 FPS。</p><p>这件事对「视频模型当世界模型」这条路线是致命的。物理定律是位移与时间的关系，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mord mathnormal">x</span><span class="mord">/Δ</span><span class="mord mathnormal">t</span></span></span></span>；如果 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span></span></span></span> 本身不可靠，那么速度、加速度、碰撞时刻这些量全部失去意义，任何基于生成视频做规划、做动力学估计的下游系统都建在流沙上。论文的立场很直白：想修一个物理缺陷，先得能测量它。本文提供的正是这把尺子。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>视频评测的主流是感知质量与语义保真：PSNR / SSIM / LPIPS 做逐帧相似度，FVD 做分布距离，VBench 与 WorldScore 做多维度打分，其中确实含有 temporal consistency、action alignment 这类「物理相邻」的维度。但这些维度问的都是「动起来像不像真的」，没有一个问「这段动作对应的物理秒数是多少」。时间尺度保真度在评测版图上是一块空白。</p><p>时间感知这条线本身也有历史。体育转播里的慢镜头检测靠领域启发式；SpeedNet 用自监督区分正常速率与人为加速的片段；arrow-of-time 研究判断视频是正放还是倒放。这些工作有一个共同的形状：把时间感知建模成<strong>二分类</strong>（快/慢、前/后）。二分类足以支撑「这段是慢镜头」的判断，却给不出「这段的物理帧率是 38.8」这样的绝对量。原因也不难理解——绝对帧率回归需要带可信真值标签的训练数据，而互联网视频的 metadata 恰恰是被后期编辑污染得最厉害的字段之一。</p><p>至于生成侧，显式几何/物理条件（depth、camera pose）已有不少工作，但时间尺度几乎从未被显式监督过，模型完全依赖数据集容器给出的 nominal FPS。训练时一段延时摄影和一段高速摄影被同样喂进网络，帧步与真实时间的对应关系就此断裂。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从已有事实出发，走到这个 idea 的路径其实相当短。第一步是观察到一个反常现象：生成视频常被描述为「smooth but slow」，社区里早有人注意到模型倾向于产出偏慢的运动。第二步是追问原因，训练语料是慢镜头、正常速率、延时摄影的混合物，而模型看不到这个混合标签，于是它学到的是「帧间过渡要合理」，学不到「一帧代表多少秒」。</p><p>第三步是关键转折：既然 metadata 不可信，能不能绕开它？SpeedNet 已经证明网络能从画面判别相对速度，说明视觉动态里确实编码了时间尺度信息。那么把二分类升级为连续回归，就能得到一个不依赖 metadata 的绝对测量器。第四步是训练数据从哪来——不能用互联网视频，因为它们本身有污染。答案是只用 metadata FPS 与物理采样率严格对齐的源（高速摄影数据集、未压缩广播序列、传感器同步的自动驾驶数据），再用受控的时间重采样人工合成各个目标帧率。论文把这一步叫 controlled temporal resampling，它同时解决了标签可信性与数据量两个问题。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>时间不是视频文件里的一个数字字段，而是画面运动本身写出来的。一个物体在两帧之间移动多远、运动模糊拖了多长、CMOS 滚动快门把直线扭曲了多少，这三样东西共同泄露了「这两帧之间过去了多少真实时间」。既然如此，就把 PhyFPS 当成一个可以从像素直接回归的连续量来学，而不是去信任那个随时可能被剪辑软件改写的容器帧率。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「足球颠球」这段真实素材为例走一遍。</p><p><strong>数据合成</strong>。所有源视频先用 RIFE 插帧统一升到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">240</span></span></span></span> FPS。对目标帧率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，取下采样比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，再用三种方式合成低帧率视频，每种对应一类真实相机机制：(1) Sharp Capture，均匀抽帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1244em;vertical-align:-0.2831em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.3383em;vertical-align:-0.497em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.378em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">⌊</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="mclose mtight">⌋</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.497em;"><span></span></span></span></span></span></span></span></span></span>，模拟高速快门，保留锐利边缘与自然的运动卡顿；(2) Motion Blur，对时间窗做平均 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1244em;vertical-align:-0.2831em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.4782em;vertical-align:-0.497em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9812em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">0</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.378em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">⌊</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="mclose mtight">⌋</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">i</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.497em;"><span></span></span></span></span></span></span></span></span></span>，曝光窗 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mord">/2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mord">/4</span><span class="mclose">}</span></span></span></span>，模拟曝光积分；(3) Rolling Shutter，按列渐进偏移采样时刻 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⌊</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mclose">⌋</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⌊</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">x</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mclose">⌋</span></span></span></span>，模拟 CMOS 逐行读出。最终得到覆盖 18 个物理帧率、共 465,535 个片段的训练集，每段统一 128 帧。</p><p><strong>模型</strong>。骨干用 VideoVAE+ 编码器提取时空 latent token。回归头不做空间池化，而是引入一个可学习的 query embedding 对 token 序列做 cross-attention 池化，这样头部与输入帧数解耦，推理时可以吃任意长度。最后 MLP 输出一个标量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span></span></span></span>，代表 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mopen">(</span><span class="mord text"><span class="mord">PhyFPS</span></span><span class="mclose">)</span></span></span></span>。训练两个变体：VC-Wide 覆盖 2 到 240 共 18 档，VC-Common 只覆盖消费级常见的 12 到 60 共 12 档。用 Adam，学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>，训练 125,000 步，4 张 RTX A6000，全局 batch 32，训练时片段最长 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">32</span></span></span></span> 帧。</p><p><strong>推理与审计</strong>。对一段待测视频，用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">32</span></span></span></span>、stride <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 的滑窗切出若干片段，逐片段预测后取平均得到视频级 PhyFPS。审计一个生成器时，把它在 100 条无速度关键词的提示上的输出全部走一遍，报告 meta FPS 与 PhyFPS 的偏差，以及片段间/视频间的变异系数。</p><p><strong>后处理</strong>。拿到预测帧率后，把视频整体重定时到平均 PhyFPS（Pred），或者按片段分别重定时（Pred Dyn）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>训练目标是对数空间的 MSE：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mtight">l</span><span class="mtight">o</span><span class="mtight" style="margin-right:0.0139em;">g</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.9291em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">n</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6514em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;">)</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></span></p><p>为什么是对数而不是直接回归帧率？因为目标值跨越 2 到 240 两个数量级。在线性空间里，把 240 预测成 230 的误差是 10，把 12 预测成 2 的误差也是 10，但后者在物理上是灾难性的（速度差 6 倍）而前者几乎无害。取对数后损失衡量的是<strong>比例误差</strong>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mord">/</span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，恰好符合时间尺度的乘性本质。论文特意指出，因为数据里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8304em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 严格为正，所以省掉了 MSLE 里常见的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">+</span><span class="mord">1</span></span></span></span> 偏置项，让损失严格反映比例缩放。</p><p>审计指标同样基于比例思想。对齐度用平均误差与百分比误差：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Pct. Error</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.1065em;vertical-align:-1.2671em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">100</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">V</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8394em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3111em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.0715em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6349em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">meta</span></span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9579em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span><span style="top:-3.2634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.0833em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">meta</span></span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>稳定性用变异系数 CV，即标准差除以均值。Intra CV 在单段视频的滑窗预测上算，衡量「同一段视频里时间尺度是否漂移」；Inter CV 在不同视频的视频级预测上算，衡量「同一模型同一配置下的时间尺度是否一致」。用 CV 而非标准差同样是为了消除绝对帧率量级的影响。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>测量器本身准不准？</strong> 在 PhyFPS-Bench-Real（4,000 个片段，训练/验证/测试来自完全不相交的视频源）上，VC-Common 的 MAE 是 3.46、MAPE 是 9%，VC-Wide 因为输出空间更宽而略差（7.76 / 21%），测试集真值平均 PhyFPS 为 38.81。</p><p><strong>能不能直接用 VLM 代替？</strong> 不能，而且差得很远。Gemini-3.1-Pro、Gemini-3-Flash、Seed-1.6、Seed-1.6-Flash、Qwen3.5 系列的 MAPE 全在 40% 以上，最差的 Qwen3.5+ 达到 91%。多个模型出现严重的 mode collapse，Seed-1.6-Flash 对任何输入都吐 30 FPS。作者还试了把视频拆成 128 张离散图片顺序输入以绕开 VLM 的抽帧预处理，仍然救不回来。这条结果对整篇论文很重要，它把「随便找个大模型当裁判」这条捷径堵死了。</p><p><strong>生成器到底有多偏？</strong> PhyFPS-Bench-Gen 审计了开源的 CogVideoX 2B/5B、HunyuanVideo、Wan2.1/2.2 四款、LTX-Video、LTX-2、InfinityStar，闭源的 Seedance-1.0-Lite/1.5-Pro、Sora-2、Grok-Imagine-T2V、Kling-o3、Veo-3.1-Fast。结论有三层。第一，偏差普遍且方向一致——几乎所有模型的 PhyFPS 都高于其 meta FPS，与「slow but smooth」的社区观察吻合。Wan2.1-1.3B 最好（Pct. Error 31%），InfinityStar 10s 最差（126%），LTX-Video 达到 99%。第二，闭源模型在绝对对齐上略优（平均误差都低于 14 FPS、百分比误差低于 60%），推测是它们在选 meta FPS 时更用心。第三也是最有意思的，闭源模型的 Intra CV 与 Inter CV <strong>并不比开源明显更好</strong>（Sora-2 是 0.13/0.29，CogVideoX-2B 是 0.11/0.46，Veo-3.1-Fast 甚至是 0.17/0.33）。作者对 LTX 系列的解释值得注意：它们 CV 低但绝对误差高，说明内部时间表示是自洽的，问题可能只出在 meta FPS 标错了，把 LTX-Video 的容器帧率从 24 改成 46.5 就能对齐。这是一个「误差来源可分解」的干净证据。</p><p><strong>修正有没有用？</strong> 用户研究收集了 15 名以上参与者的 1,490 次成对比较，用 Bradley-Terry 模型估计偏好强度。原始视频只拿到 19.0%，全局重定时 Pred 拿到 44.2%，动态分段重定时 Pred Dyn 拿到 36.9%。作者的假设是，在一段短视频内部变换播放帧率反而引入了新的不一致感，所以更精细的局部修正反而不如统一平均。</p><p><strong>消融</strong>。去掉 motion blur 与 rolling shutter 增强、只用均匀抽帧的朴素基线，MAE 从 3.46 退化到 5.12；只加 motion blur 是 4.87。推理窗口长度上，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">32</span></span></span></span> 最优，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span> 仍有竞争力，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 反而不如 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span>，因为整段一次性推理失去了滑窗集成的方差削减，也测不出片段内的帧率波动。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：视频生成模型有一个从未被测量过的缺陷，它们不知道自己画的一秒有多长。作者把这个缺陷命名为 chronometric hallucination，并定义 PhyFPS 作为区别于容器 metadata 的内在时间尺度。测量方法是在受控时间重采样合成的 46.5 万片段上，用 VideoVAE+ 加 query 池化头回归 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span></span></span></span> PhyFPS，MAE 3.46、MAPE 9%。审计 18 个主流生成器发现偏差普遍、方向一致地偏慢，且闭源模型在稳定性上并不占优。按预测帧率整体重定时能把人类偏好从 19.0% 提到 44.2%。</p><p><strong>三句话版</strong>：视频模型的时间尺度是幻觉出来的，容器帧率不可信。Visual Chronometer 从画面动态直接回归物理帧率，精度远超所有被测 VLM。审计显示主流生成器普遍偏慢且时间尺度不稳定，简单重定时即可显著改善观感。</p><p><strong>一句话版</strong>：给视频生成器装一块能读出「这一秒有多长」的秒表，然后发现所有生成器的秒表都是坏的。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>训练数据里 meta FPS 等于 PhyFPS 的那批源视频，其内容分布足以覆盖生成视频的内容分布</strong>。整套方法的真值完全建立在「这些源没有被后期时间重映射」之上，而这些源是高速摄影数据集、未压缩广播序列、传感器同步驾驶数据和人体动捕——它们在场景类型上高度偏向可控拍摄与结构化运动。生成视频审计用的 100 条提示却刻意覆盖了火、雨、风、流体、多智能体这些类别。</p><p>如果测量器在这些分布外内容上系统性偏高，那么「所有生成器都偏慢」这个核心结论就有了一个平凡的替代解释：不是生成器慢，是测量器把陌生内容读高了。论文提供的证据是跨源严格划分的 PhyFPS-Bench-Real，这确实排除了源内过拟合，但它没有直接回答「真实分布 vs 生成分布」的迁移问题——测试集仍来自与训练集同类型的采集流程，而不是生成视频。作者也没有在生成视频上给出任何独立的 PhyFPS 真值校验（这类真值本身很难获得）。用户研究是唯一的间接支撑：如果预测系统性偏高，按预测重定时应当让视频变得不自然，但人类明显更偏好修正后的版本，这在方向上支持了预测的有效性，只是它证明的是「修正让观感更好」，不等于「预测数值准确」。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现完整训练。一周方案如下。</p><ul><li><strong>数据</strong>：从 Adobe240 或任意 120 FPS 公开素材里取 200 段，用与论文相同的三种方式合成 8 个目标帧率的版本，得到约 4,800 个带真值片段。</li><li><strong>实现</strong>：不训练 VideoVAE+，改用冻结的现成视频编码器（例如 VideoMAE）提特征，只训练一个轻量 attention 池化头加 MLP，目标是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span></span></span></span> PhyFPS 的 MSE。这把训练成本压到单卡数小时。</li><li><strong>测量</strong>：先在留出源上测 MAE/MAPE，确认能到 20% 以内（不必达到论文的 9%，只要显著优于随机与常数预测）。然后用 Wan2.1-1.3B 和 CogVideoX-2B 各生成 50 段无速度关键词的视频，报告 PhyFPS 均值与 meta FPS 的偏差方向。</li><li><strong>判定</strong>：若两个模型的预测 PhyFPS 都系统性高于 24，且偏差方向与论文表 1 一致（Wan 偏差小于 CogVideoX），则支持论文结论；若偏差方向随机或两模型排序颠倒，则说明该信号对骨干与训练规模高度敏感，论文的绝对数值不可迁移。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击点是**「偏慢」可能是内容偏置而非时间偏置**。生成模型有一个普遍倾向：偏好低动态度的输出（VBench 的 dynamic degree 维度上开源模型普遍偏低）。一个画面里如果人走得少、镜头动得慢，测量器看到的位移小、模糊少，理应给出<strong>低</strong>的 PhyFPS 才对——但论文观察到的是预测值一致<strong>偏高</strong>。这个方向看起来与内容偏置相反，反而是对论文有利的。</p><p>所以更锋利的反例应当针对测量器对生成伪影的响应。设计一个实验：取同一段真实视频，人为注入三类生成模型典型伪影——帧间闪烁、局部纹理抖动、轻微时序抖动（jitter）——但<strong>不改变</strong>任何真实的运动速度。然后测量 Visual Chronometer 的预测是否漂移。假说是：这些高频伪影在视觉上等价于「更大的帧间变化」，会被模型读成「时间间隔更长」，从而系统性推高 PhyFPS。如果这个假说成立，那么「生成器偏慢」的整个审计结论就会坍缩成「生成器有伪影」的重述，而 Table 1 里的排序也就变成了伪影强度排序而非时间尺度排序。论文里 LTX-Video 那条（CV 低但绝对误差 99%）恰好可以被这个替代解释吃掉。</p><p>论文对此没有直接的对照实验，这是它最需要补的一块。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：Visual Chronometer 是一个事后测量器，它只能诊断，不能治疗；论文自己在讨论里也承认，真正的解法要么在数据层面重标注，要么在架构层面加时间条件，要么把它当 reward 做偏好对齐。这三条都是把时间当作一个<strong>标量条件</strong>处理，仍然假设一段视频有单一的物理帧率。</p><p><strong>新 framing</strong>：把时间尺度从「视频级标量」提升为「场景级的每物体属性」。同一个画面里，飘落的树叶、行驶的车、拍打的翅膀完全可以处在不同的有效时间常数上——现实中它们共享一个时钟，而生成模型很可能对不同物体隐式地用了不同时钟。这是一个比全局帧率漂移严重得多的失效模式：全局漂移只是整体放慢，局部时钟不一致则直接破坏物体之间的因果关系（球先落地还是脚先着地）。</p><p><strong>可借鉴的相邻工具</strong>：多目标跟踪与光流的实例分割能给出物体级的运动场；音视频同步领域的 audio-visual synchrony 检测已有成熟的「两路信号是否共享时基」的判别方法，可以直接改造成「两个物体区域是否共享时基」的判别器。</p><p><strong>第一个实验</strong>：用现成的实例分割把生成视频切成前景物体与背景，对每个区域独立跑 Visual Chronometer（滑窗内只在该 mask 内采样），得到每物体的 PhyFPS 轨迹。度量指标是同一视频内不同物体 PhyFPS 的离散度。真实视频上这个离散度应当接近 0（受噪声限制），生成视频上如果显著大于 0，就直接证明了「模型内部存在多个不一致的时钟」这一全新的失效模式，而且这个指标不需要任何真值标注，天然是自校准的。</p>',54)])])}const y=a(l,[["render",e]]);export{o as __pageData,y as default};
